<main class="invite <?= View::e($item['template_code']) ?> color-<?= View::e($item['color_preset']??'forest') ?> font-<?= View::e($item['font_preset']??'sans') ?> button-<?= View::e($item['button_preset']??'rounded') ?>"><header class="hero"><p class="church"><?= View::e($item['church_name']) ?></p><h1><?= View::e($item['title']) ?></h1><?php if($item['summary']): ?><p class="lead"><?= View::e($item['summary']) ?></p><?php endif; ?><?php if($item['hero_uuid']): ?><img class="hero-image" src="/media/<?= View::e($item['hero_uuid']) ?>" alt="" loading="eager"><?php endif; ?></header>
