<section id="apply" class="apply"><h2>참석 신청</h2><?php if($success): ?><div class="notice success"><?= View::e($success) ?></div><?php endif; ?><?php if($error): ?><div class="notice error"><?= View::e($error) ?></div><?php endif; ?>
