<script>document.getElementById('share')?.addEventListener('click',async()=>{const token='<?= View::e(Csrf::token()) ?>';fetch(location.pathname+'/share',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'_token='+encodeURIComponent(token)});if(navigator.share){await navigator.share({title:document.title,url:location.href});}else{await navigator.clipboard.writeText(location.href);alert('초대장 주소를 복사했습니다.');}});</script>
